/* HEXA BATTLEGROUNDS setup — PART 30 OF 84. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-fruit-4', 'fruit', 'mission', 'Fruit Slash', 'game', 1, array['any','food','healing','social','costa','sports','market']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍓","d":6},{"f":"🍇","d":5},{"f":"🍊","d":0},{"f":"🍎","d":4},{"f":"🍌","d":2},{"f":"🥭","d":7}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🍇   🍌   🍎   🍊\n(Grapes, Banana, Apple, Orange)","big":true},"decoder":{"title":"Scramble rule","body":"Swap the first two digits and the last two digits."}}'::jsonb, '[{"label":"4-digit vault code","accept":["2504"]}]'::jsonb, false, 3, 200, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🍇=5 🍌=2 🍎=4 🍊=0 → pairs swapped → 2504', null, 25, 'published'), ('mission-fruit-5', 'fruit', 'mission', 'Fruit Slash', 'game', 1, array['any','food','healing','social','costa','sports','market']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍉","d":4},{"f":"🍎","d":5},{"f":"🍊","d":1},{"f":"🥭","d":8},{"f":"🍌","d":3},{"f":"🥝","d":9}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🍎   🥝   🍌   🍉\n(Apple, Kiwi, Banana, Watermelon)","big":true},"decoder":{"title":"Scramble rule","body":"Add 1 to every digit (9 becomes 0)."}}'::jsonb, '[{"label":"4-digit vault code","accept":["6045"]}]'::jsonb, false, 3, 200, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🍎=5 🥝=9 🍌=3 🍉=4 → +1 to each digit → 6045', null, 25, 'published'), ('airdrop-fruit-10', 'fruit', 'airdrop', 'Fruit Slash', 'game', 1, array['any']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🥝","d":9},{"f":"🥭","d":1},{"f":"🍊","d":7},{"f":"🍉","d":5},{"f":"🍍","d":0},{"f":"🍓","d":8}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🥝   🍊   🍉   🥭\n(Kiwi, Orange, Watermelon, Mango)","big":true},"decoder":{"title":"Scramble rule","body":"Add 1 to every digit (9 becomes 0)."}}'::jsonb, '[{"label":"4-digit vault code","accept":["0862"]}]'::jsonb, false, 3, 150, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🥝=9 🍊=7 🍉=5 🥭=1 → +1 to each digit → 0862', null, 25, 'published'), ('airdrop-fruit-11', 'fruit', 'airdrop', 'Fruit Slash', 'game', 1, array['any']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🥭","d":3},{"f":"🍌","d":8},{"f":"🍉","d":4},{"f":"🥝","d":6},{"f":"🍓","d":5},{"f":"🍎","d":9}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🍌   🥝   🍓   🥭\n(Banana, Kiwi, Strawberry, Mango)","big":true},"decoder":{"title":"Scramble rule","body":"Read the digits in REVERSE order."}}'::jsonb, '[{"label":"4-digit vault code","accept":["3568"]}]'::jsonb, false, 3, 150, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🍌=8 🥝=6 🍓=5 🥭=3 → reversed → 3568', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('airdrop-fruit-12', 'fruit', 'airdrop', 'Fruit Slash', 'game', 1, array['any']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍌","d":0},{"f":"🍍","d":1},{"f":"🍇","d":9},{"f":"🍎","d":3},{"f":"🍒","d":2},{"f":"🥝","d":8}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🍌   🍒   🍇   🥝\n(Banana, Cherry, Grapes, Kiwi)","big":true},"decoder":{"title":"Scramble rule","body":"Subtract each digit from 9."}}'::jsonb, '[{"label":"4-digit vault code","accept":["9701"]}]'::jsonb, false, 3, 150, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🍌=0 🍒=2 🍇=9 🥝=8 → 9 minus each digit → 9701', null, 25, 'published'), ('airdrop-fruit-13', 'fruit', 'airdrop', 'Fruit Slash', 'game', 1, array['any']::text[], 'Scout plays Fruit Slash: slicing a fruit reveals its hidden digit. Intel knows which fruits make the vault code. Decoder knows how to scramble it.', '{"scout":{"title":"Fruit Slash","body":"Swipe across flying fruit to slice it. Each fruit type always hides the same digit. Avoid the 💣 (it just costs you time). Call out what you find.","game":{"type":"fruit","fruits":[{"f":"🍊","d":2},{"f":"🍉","d":7},{"f":"🥭","d":9},{"f":"🍍","d":5},{"f":"🥝","d":0},{"f":"🍌","d":3}],"bomb":true,"seconds":30}},"intel":{"title":"Vault order","body":"🥝   🍊   🍉   🍌\n(Kiwi, Orange, Watermelon, Banana)","big":true},"decoder":{"title":"Scramble rule","body":"Add 3 to every digit and keep only the last digit (8 → 1)."}}'::jsonb, '[{"label":"4-digit vault code","accept":["3506"]}]'::jsonb, false, 3, 150, 'Scout: shout every fruit and digit you slice. Intel: tell everyone which four fruits matter, in order.', '🥝=0 🍊=2 🍉=7 🍌=3 → +3 to each digit, last digit only → 3506', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); alter table arenas add column if not exists autopilot boolean not null default false; alter table arenas add column if not exists auto_step text; alter table arenas add column if not exists auto_next_at timestamptz; alter table arenas add column if not exists auto_story int not null default -1; alter table arenas add column if not exists auto_length text; create or replace function _auto_preset(p_length text) returns jsonb language sql immutable as $$ select case coalesce(p_length, 'standard') when 'quick' then jsonb_build_object('auto_pacing', 1, 'phase_schedule', '1,3,5,7', 'finale_minute', 9, 'finale_battles', 1, 'zone_warning', 25, 'airdrop_interval', 1, 'red_interval', 2, 'mission_time_pct', 70, 'shuttle_seconds', 12, 'roles_seconds', 12, 'sync_seconds', 90, 'recovery_seconds', 45, 'attack_cooldown', 45, 'protect_seconds', 45, 'boarding_seconds', 12, 'airdrop_window', 90) when 'full' then jsonb_build_object('auto_pacing', 1, 'phase_schedule', '3,15,30,45', 'finale_minute', 55, 'finale_battles', 3, 'zone_warning', 60, 'airdrop_interval', 5, 'red_interval', 6, 'mission_time_pct', 100, 'shuttle_seconds', 20, 'roles_seconds', 15, 'sync_seconds', 0, 'recovery_seconds', 120, 'attack_cooldown', 90, 'protect_seconds', 120, 'boarding_seconds', 25, 'airdrop_window', 180) else jsonb_build_object('auto_pacing', 1, 'phase_schedule', '2,6,11,16', 'finale_minute', 21, 'finale_battles', 2, 'zone_warning', 40, 'airdrop_interval', 3, 'red_interval', 4, 'mission_time_pct', 85, 'shuttle_seconds', 15, 'roles_seconds', 15, 'sync_seconds', 120, 'recovery_seconds', 75, 'attack_cooldown', 60, 'protect_seconds', 75, 'boarding_seconds', 18, 'airdrop_window', 120) end $$; create or replace function _auto_story(p_phase int) returns text[] language sql immutable as $$ select case p_phase when 0 then array['Squad 00: we are already inside', 'Welcome to Operation Siruseri. We have been on this campus longer than you. Find the codes before we find you.'] when 1 then array['Squad 00: supplies are out there', 'We hid supplies across the campus. Search every building. Crates will fall from the sky — be first.'] when 2 then array['Squad 00: duels are live', 'From now on, any squad close to you can challenge you. Trust carefully. Even allies can turn.'] when 3 then array['Squad 00: the circle is closing', 'The safe zone is shrinking toward the centre. Stay inside it, or keep running.'] else array['Squad 00: everyone ends in Room 14', 'Training Room 14 is where this ends. Make your last points count — the finale is coming.'] end $$; create or replace function _auto_finale_minute(p_ev uuid) returns int language plpgsql stable as $$ declare v int; v_s text[]; begin v := coalesce(_cfg(p_ev, 'finale_minute'), 0); if v > 0 then return v; end if; v_s := string_to_array(_cfg_text(p_ev, 'phase_schedule'), ','); begin v := nullif(trim(v_s[array_length(v_s, 1)]), '')::int; exception when others then v := null; end; return coalesce(v, 50) + 5; end $$; create or replace function _auto_fin_pos(p_arena uuid) returns int language plpgsql stable as $$ declare a arenas; v_n int; v_k int; v_rev boolean; v_pos int; begin select * into a from arenas where id = p_arena; v_n := greatest(1, coalesce(_cfg(a.event_id, 'finale_battles'), 2)); if a.results_locked or a.phase in ('results', 'ended') then if not a.winner_revealed then return 5 + v_n; end if; if (select count(*) from arenas x where x.event_id = a.event_id and exists (select 1 from teams where arena_id = x.id and ready)) > 1 and not (select grand_revealed from events where id = a.event_id) then return 6 + v_n; end if; return 7 + v_n; end if; select count(*) into v_k from sync_rounds where arena_id = a.id; v_rev := exists (select 1 from story_events where arena_id = a.id and kind = 'reveal'); v_pos := least(v_k, 2 + v_n); if v_k >= 3 + v_n then return 4 + v_n; end if; if v_rev and v_pos >= 2 + v_n then return 3 + v_n; end if; return v_pos; end $$; create or replace function _auto_step_name(p_pos int, p_n int) returns text language sql immutable as $$ select case when p_pos <= 0 then 'Finale entry round' when p_pos = 1 then 'Exchange round' when p_pos <= 1 + p_n then 'Finale battle ' || p_pos when p_pos = 2 + p_n then 'Squad 00 reveal' when p_pos = 3 + p_n then 'Final code' when p_pos = 4 + p_n then 'Results locked' when p_pos = 5 + p_n then 'Winner reveal' when p_pos = 6 + p_n then 'Grand champion' else 'Match complete' end $$; create or replace function _auto_status(p_arena uuid) returns jsonb language plpgsql stable as $$ declare a arenas; v_label text; v_at timestamptz; v_n int; v_pos int; v_fm int; r sync_rounds; begin select * into a from arenas where id = p_arena; if a.id is null or not a.autopilot then return jsonb_build_object('on', false); end if; v_n := greatest(1, coalesce(_cfg(a.event_id, 'finale_battles'), 2)); v_fm := _auto_finale_minute(a.event_id); case when a.phase = 'lobby' then v_label := 'Waiting for a ready squad'; when a.phase = 'boarding' then v_label := 'Bus leaves'; v_at := a.auto_next_at; when a.phase = 'shuttle' then v_label := 'Bus arrives'; v_at := a.shuttle_arrive_at; when a.phase = 'roles' then v_label := 'Roles lock'; v_at := a.roles_deadline; when a.phase = 'play' then if a.match_phase < 4 and a.phase_next_at is not null then v_label := 'Phase ' || (a.match_phase + 1); v_at := a.phase_next_at; else v_label := 'Finale'; v_at := a.play_started_at + make_interval(mins => v_fm); end if; when a.phase in ('finale', 'results') then if a.sync_round_id is not null then select * into r from sync_rounds where id = a.sync_round_id; v_label := 'Round ends'; v_at := r.deadline; else v_pos := _auto_fin_pos(a.id); v_label := _auto_step_name(v_pos, v_n); if v_pos < 7 + v_n then v_at := a.auto_next_at; end if; end if; else v_label := 'Match complete'; end case; return jsonb_build_object('on', true, 'step', a.auto_step, 'label', v_label, 'at', v_at, 'length', a.auto_length, 'paused', a.paused); end $$; create or replace function _auto_resync(p_arena uuid) returns void language plpgsql as $$ declare a arenas; begin select * into a from arenas where id = p_arena; update arenas set auto_step = case when a.phase in ('lobby', 'boarding') then 'boarding' when a.phase in ('shuttle', 'roles') then 'ride' when a.phase = 'play' then 'play' when a.phase in ('finale', 'results') then 'fin:' || _auto_fin_pos(a.id) else 'done' end, auto_next_at = case when a.phase = 'boarding' then coalesce(a.auto_next_at, now() + _secs(coalesce(_cfg(a.event_id, 'boarding_seconds'), 18))) when a.phase in ('finale', 'results') then now() + interval '10 seconds' else null end where id = p_arena; end $$;
